CREATE TABLE IF NOT EXISTS channels (id text PRIMARY KEY, data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS credentials (id text PRIMARY KEY, channel_id text NOT NULL REFERENCES channels(id) ON DELETE CASCADE, data jsonb NOT NULL, secret text NOT NULL);
CREATE INDEX IF NOT EXISTS credentials_channel_idx ON credentials(channel_id);
CREATE TABLE IF NOT EXISTS settings (id text PRIMARY KEY, data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS api_keys (id text PRIMARY KEY, token_hash text NOT NULL UNIQUE, data jsonb NOT NULL, used bigint NOT NULL DEFAULT 0 CHECK (used >= 0));
CREATE TABLE IF NOT EXISTS profile_usage (key_id text NOT NULL REFERENCES api_keys(id) ON DELETE CASCADE, profile_id text NOT NULL, used bigint NOT NULL DEFAULT 0 CHECK (used >= 0), PRIMARY KEY(key_id, profile_id));
CREATE TABLE IF NOT EXISTS tags (name text PRIMARY KEY);
CREATE TABLE IF NOT EXISTS request_logs (id text PRIMARY KEY, created_at timestamptz NOT NULL, channel_id text, result text NOT NULL, model text NOT NULL, source text NOT NULL, data jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS request_logs_created_idx ON request_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS request_logs_channel_idx ON request_logs(channel_id, created_at DESC);
CREATE INDEX IF NOT EXISTS request_logs_result_idx ON request_logs(result, created_at DESC);
CREATE TABLE IF NOT EXISTS attempts (id text PRIMARY KEY, request_id text NOT NULL REFERENCES request_logs(id) ON DELETE CASCADE, channel_id text NOT NULL, started_at timestamptz NOT NULL, data jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS attempts_request_idx ON attempts(request_id, started_at);
CREATE INDEX IF NOT EXISTS attempts_channel_idx ON attempts(channel_id, started_at DESC);
CREATE TABLE IF NOT EXISTS events (id text PRIMARY KEY, created_at timestamptz NOT NULL, data jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS events_created_idx ON events(created_at DESC);
CREATE TABLE IF NOT EXISTS gateway_accounts (channel_id text PRIMARY KEY REFERENCES channels(id) ON DELETE CASCADE, data jsonb NOT NULL, secret text NOT NULL);
CREATE TABLE IF NOT EXISTS gateway_state (id text PRIMARY KEY, value text NOT NULL, expires_at timestamptz);
CREATE TABLE IF NOT EXISTS channel_rate_limits (channel_id text NOT NULL REFERENCES channels(id) ON DELETE CASCADE, minute bigint NOT NULL, requests bigint NOT NULL DEFAULT 0, tokens bigint NOT NULL DEFAULT 0, PRIMARY KEY(channel_id,minute));
CREATE TABLE IF NOT EXISTS credential_balance_jobs (credential_id text PRIMARY KEY REFERENCES credentials(id) ON DELETE CASCADE, next_refresh_at bigint NOT NULL DEFAULT 0, lease_until bigint NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS credential_balance_jobs_due_idx ON credential_balance_jobs(next_refresh_at,lease_until);
